<?php
require_once '../../config/auth.php';
requestMethod('POST');
$user=requireLogin();
$data=getRequestData(); $category=$data['category']??''; $map=['House Listings'=>'listings','Roommate Profile'=>'roommate','Technical Issue'=>'technical_issue','Comments'=>'comment','User'=>'user','listing'=>'listings','listings'=>'listings','roommate'=>'roommate','technical_issue'=>'technical_issue','comment'=>'comment','user'=>'user']; $category=$map[$category]??$category; $title=trim($data['title']??''); if(!in_array($category,['listings','roommate','technical_issue','comment','user'],true)||$title==='') jsonError('Valid category and title are required.');
try{ $db=getDB(); $path=null; if(!empty($_FILES['image'])||!empty($_FILES['report_image'])){ $field=!empty($_FILES['image'])?'image':'report_image'; $path=safeUpload($field,'uploads/reports',['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'],5*1024*1024); } $stmt=$db->prepare('INSERT INTO reports (reported_by_user_id,category,title,description,image_path,reference_id) VALUES (?,?,?,?,?,?)'); $stmt->execute([currentUserId(),$category,$title,trim($data['description']??''),$path,($data['reference_id']??'')!==''?(int)$data['reference_id']:null]); $id=(int)$db->lastInsertId(); notifyAdmins($db,'system','New report submitted by '.($user['name']??'a student').': '.$title,$id); logActivity($db,currentUserId(),'submit_report','Submitted report #'.$id); jsonResponse(['success'=>true,'report_id'=>$id]); }catch(Throwable $e){ jsonError('Could not submit report.',500); }
